set -euo pipefail
upload_dir=$(getent passwd "$SUDO_USER" | cut -d: -f6)
root=/var/lib/news-flow/qc-complete27-20261122
cd /opt/news-flow/current
runuser -u news-flow -- /opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {gunzipSync,gzipSync} from 'node:zlib';import {createHash} from 'node:crypto';import {createRequire} from 'node:module';import {loadNewsRegistry} from './src/newsFlow/registry.mjs';import {NewsHttpDriver,NewsProxyPool} from './src/newsFlow/transport.mjs';import {NewsNetworkPool} from './src/newsFlow/networkPool.mjs';const require=createRequire('/opt/news-flow/current/package.json'),ch=require('cheerio'),root='/var/lib/news-flow/qc-complete27-20261122',registry=await loadNewsRegistry(),pool=await NewsProxyPool.load('/etc/news-flow/proxies.json',{rotation:'request'}),network=new NewsNetworkPool({workers:1}),driver=new NewsHttpDriver({state:{cacheResponses:false,failedUrl:()=>false,request:()=>null,reserve:()=>true,cache:()=>null,completeHttpResponse:()=>{}},network,pool,allowedDomains:[...registry.allowedDomains,'apife.baobinhduong.vn'],siteCooldown:false,maxWireRequests:12}),UA='Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0.0.0 Safari/537.36',jobs=[{site:'finance.biggo.com',url:'https://finance.biggo.com/news/383d64f9-5e19-49f2-86cb-34d51c915679'},{site:'vietnamfdi.vn',url:'http://vietnamfdi.vn/'},{site:'dailo.vn',url:'http://m.dailo.vn/'}],old=JSON.parse(fs.readFileSync('/var/lib/news-flow/qc-remaining27-all-20261122/all-probe.json')),vfi=old.sites.find(s=>s.site==='vietnamfdi.vn');if(vfi.articles[0])jobs.push({site:vfi.site,url:vfi.articles[0].url.replace('https:','http:')});const declared=JSON.parse(fs.readFileSync('/var/lib/news-flow/qc-remaining27-all-20261122/declared-extra.json')).checks.find(p=>p.site==='truyenhinh.baobinhduong.vn');if(declared)jobs.push({site:declared.site,url:declared.url.replace('https:','http:')});const report={at:new Date().toISOString(),checks:[],clockMarkup:[]};try{for(const j of jobs){const p=await driver.get('qc27-extra-'+j.site,j.url,registry.sources.get(j.site).config,[],{reviewFailed:true,taskRole:'review',headers:{'User-Agent':UA}}),o={...j,error:p.error,statusCode:p.statusCode,finalUrl:p.finalUrl};if(p.html){o.file=root+'/evidence/'+createHash('sha256').update(p.html).digest('hex')+'.gz';fs.writeFileSync(o.file,gzipSync(p.html));o.title=ch.load(p.html)('title').text();}report.checks.push(o);console.log(JSON.stringify(o));}
for(const site of ['dulichgiaitri.com','danhgiaxe.com']){const s=old.sites.find(s=>s.site===site);for(const p of s.articles.filter(p=>p.file&&!p.error)){const html=gunzipSync(fs.readFileSync(p.file)).toString(),$=ch.load(html);report.clockMarkup.push({site,url:p.url,nodes:$('time').toArray().slice(0,3).map(e=>({attr:$(e).attr(),text:$(e).text(),parent:$(e).parent().parent().text().replace(/\s+/g,' ').slice(0,200)})),originalHints:html.match(/.{0,50}(?:datePublished|article:published|pubdate|post_date|publish_date).{0,130}/g)?.slice(0,4)});}}
fs.writeFileSync(root+'/extra-controls.json',JSON.stringify(report,null,2));console.log(JSON.stringify({clockMarkup:report.clockMarkup}));}finally{await network.close();}
NODE
install -o "$SUDO_USER" -m 0600 "$root/extra-controls.json" "$upload_dir/.qc27-complete-extra-controls.json"
